    H,W=len(grid),len(grid[0])
    bg=max(set(sum(grid,[])), key=lambda v:sum(row.count(v) for row in grid))
    marker={v for v in set(sum(grid,[]))-{bg}}
    out=[row[:] for row in grid]
    # also columns
    for r in range(H):
        ms=[c for c in range(W) if grid[r][c]==marker]
        for a,b in zip(ms[:-1],ms[1:]):
            for c in range(a+1,b):
